window.JLPT=window.JLPT||{};window.JLPT[11]={"week":11,"days":[{"day":0,"title":"모의① 문자·어휘 20문제","vocab":[{"w":"運動","r":"うんどう","m":"운동","au":"58be74d35e75","rep":1},{"w":"世界","r":"せかい","m":"세계","au":"fb475ac00248","rep":1},{"w":"説明","r":"せつめい","m":"설명","au":"733b74466dae","rep":1},{"w":"試験","r":"しけん","m":"시험","au":"662e8af0c32f","rep":1},{"w":"住所","r":"じゅうしょ","m":"주소","au":"11112467a928","rep":1},{"w":"地図","r":"ちず","m":"지도","au":"5fb9b84e98c2","rep":1},{"w":"意見","r":"いけん","m":"의견","au":"2d4f73942bf7","rep":1},{"w":"計画","r":"けいかく","m":"계획","au":"7632bfa586a1","rep":1},{"w":"工場","r":"こうじょう","m":"공장","au":"81fad013229f"},{"w":"特別","r":"とくべつ","m":"특별(함)","au":"749043f60a04","rep":1},{"w":"安心","r":"あんしん","m":"안심","au":"a66dc7547ac6","rep":1},{"w":"用事","r":"ようじ","m":"볼일, 용무","au":"af377da7a4d2","rep":1},{"w":"近所","r":"きんじょ","m":"근처, 이웃","au":"ec385189dd31","rep":1},{"w":"食堂","r":"しょくどう","m":"식당","au":"59fda3fa2a30"},{"w":"会場","r":"かいじょう","m":"(행사)장, 회장","au":"2d4b8af2b5e3","rep":1}],"lesson":{"summary":"실제 시험의 '언어지식(문자·어휘) 25분'을 떠올리며 20문제를 한 번에 풉니다. 오늘은 유형별 시간 배분과 풀이 순서를 몸에 익히는 날입니다.","points":["실제 N4 문자·어휘는 25분에 약 28문제(読み 7·表記 5·文脈 8·言い換え 4·用法 4)입니다. 한 문제 평균 50초 이하로 풀어야 마지막에 검토할 시간이 남습니다.","푸는 순서: 読み·表記는 보자마자 답하고(30초), 文脈은 빈칸 앞뒤 단어와 함께 읽고(40초), 시간이 걸리는 言い換え·用法에 남은 시간을 씁니다.","読み 함정 4가지: 장음(こう/こ), 탁음(し/じ), 촉음(っ), 요음(しょ/しよ). 보기를 한 글자씩 소리 내어 비교하세요.","表記 함정: 모양이 비슷한 한자(待/持/特, 地/池). 왼쪽 부분의 뜻(彳=가다, 扌=손, 牜=소)을 떠올리면 구별이 쉽습니다.","用法은 보기마다 그 단어 자리에 한국어 뜻을 넣어 읽어 보세요. 어색한 문장이 바로 보입니다.","모르는 문제는 30초 안에 하나 골라 표시하고 넘어갑니다. 빈칸으로 두지 않는 것이 원칙입니다."],"table":{"head":["유형","실제 문항(약)","1문제 목표","핵심 요령"],"rows":[["読み","7","30초","장음·탁음·촉음 확인"],["表記","5","30초","비슷한 한자 구별"],["文脈","8","40초","빈칸 앞뒤 단어와 짝"],["言い換え","4","50초","밑줄 부분만 바꿔 넣기"],["用法","4","1분","뜻이 문장에 맞는지"],["검토","-","3분","표시한 문제만 다시"]]},"examples":[{"jp":"試験の 前の 日は 早く ねます。","r":"しけんの まえの ひは はやく ねます。","ko":"시험 전날은 일찍 잡니다.","au":"d630549166f3"},{"jp":"地図を 見ながら 会場まで 歩きました。","r":"ちずを みながら かいじょうまで あるきました。","ko":"지도를 보면서 행사장까지 걸었습니다.","au":"837b03820dc6"},{"jp":"用事が あるので、先に 帰っても いいですか。","r":"ようじが あるので、さきに かえっても いいですか。","ko":"볼일이 있어서 먼저 가도 될까요?","au":"8f6693d92552"},{"jp":"子どもの ねつが 下がって、安心しました。","r":"こどもの ねつが さがって、あんしんしました。","ko":"아이 열이 내려서 안심했습니다.","au":"c683f69ca584"}]},"drills":[{"part":"読み","q":"こんどの <u>試験<\/u>は 来週の 月曜日です。","choices":["しっけん","しげん","じけん","しけん"],"a":3,"ex":"試験은 「しけん」입니다. 「じけん(事件)」은 탁음 함정, 「しっけん」은 촉음 함정입니다."},{"part":"読み","q":"毎朝 こうえんで <u>運動<\/u>を して います。","choices":["うんど","うんどう","うどう","うんとう"],"a":1,"ex":"運動은 「うんどう」로 장음 う와 탁음 ど가 모두 필요합니다. 「うんど」는 장음을 뺀 함정입니다."},{"part":"読み","q":"先生の <u>説明<\/u>は とても わかりやすかったです。","choices":["せいめい","せつめ","せっめい","せつめい"],"a":3,"ex":"説明은 「せつめい」입니다. 「せいめい」는 生命(생명)의 읽기이고, 「せつめ」는 장음 い를 뺀 함정입니다."},{"part":"読み","q":"ここに お名前と <u>住所<\/u>を 書いて ください。","choices":["じゅうしょ","じゅうじょ","じゅしょ","じゅうしょう"],"a":0,"ex":"住所는 「じゅうしょ」. 住의 장음(じゅう)과 所의 단음(しょ)을 함께 기억하세요."},{"part":"読み","q":"この 町には 大きな <u>工場<\/u>が あります。","choices":["こうじょう","こうじょ","こうしょう","くうじょう"],"a":0,"ex":"工場은 「こうじょう」로 두 글자 모두 장음입니다. 「こうじょ」는 장음을 하나 뺀 함정입니다."},{"part":"読み","q":"日曜日は <u>近所<\/u>の 店で 買い物を します。","choices":["きんじょう","ちかじょ","きんしょ","きんじょ"],"a":3,"ex":"近所는 「きんじょ」. 所가 여기서는 탁음 「じょ」가 되고 장음이 없습니다."},{"part":"表記","q":"<u>とくべつ<\/u>な 日には 家族で レストランへ 行きます。","choices":["持別","特別","特列","待別"],"a":1,"ex":"「とくべつ」는 特別. 持(もつ)·待(まつ)는 모양이 비슷한 함정, 列은 別과 비슷한 함정입니다."},{"part":"表記","q":"わたしの <u>いけん<\/u>を 聞いて ください。","choices":["音見","意見","意験","意現"],"a":1,"ex":"「いけん」은 意見. 意 아래쪽 心을 빼면 音이 되니 주의하세요."},{"part":"表記","q":"夏休みの <u>けいかく<\/u>を 立てました。","choices":["計面","討画","計画","計田"],"a":2,"ex":"「けいかく」는 計画. 画와 面은 모양이 비슷한 함정입니다."},{"part":"表記","q":"駅の 前で <u>ちず<\/u>を 見ました。","choices":["地図","他図","池図","地区"],"a":0,"ex":"「ちず」는 地図. 池(いけ)·他는 모양 함정, 地区는 「ちく」라고 읽는 다른 단어입니다."},{"part":"文脈","q":"きょうは（　　）が あるので、先に 帰ります。","choices":["計画","意見","用事","世界"],"a":2,"ex":"'먼저 돌아갈 이유'가 되는 것은 볼일(用事)입니다. 計画가 있어서 먼저 간다는 말은 부자연스럽습니다."},{"part":"文脈","q":"子どもから「ぶじに 着いたよ」と 電話が あって、（　　）しました。","choices":["特別","安心","世界","運動"],"a":1,"ex":"무사히 도착했다는 연락을 받고 '안심했다(安心しました)'가 자연스럽습니다. 運動しました·特別しました는 전화 내용과 맞지 않습니다."},{"part":"文脈","q":"パーティーの（　　）は ホテルの 三階です。","choices":["食堂","工場","会場","近所"],"a":2,"ex":"파티가 열리는 장소는 会場입니다. 食堂은 밥을 먹는 곳이라 '파티의 식당'은 어색합니다."},{"part":"文脈","q":"この 歌は（　　）中の 人に 知られて います。","choices":["住所","計画","地図","世界"],"a":3,"ex":"「世界中(せかいじゅう)」는 '온 세계'. 「～中」가 붙어 '전체'를 나타내는 표현입니다."},{"part":"文脈","q":"雨の 日は 道が すべりやすいので、（　　）運転して ください。","choices":["ぐっすり","ゆっくり","はっきり","すっかり"],"a":1,"ex":"미끄러우니 '천천히(ゆっくり)' 운전하라는 뜻입니다. はっきり는 분명히, すっかり는 완전히, ぐっすり는 푹(자다)."},{"part":"文脈","q":"この パソコンは 古くて、もう（　　）。","choices":["合いません","始まりません","動きません","集まりません"],"a":2,"ex":"기계가 작동하지 않을 때는 「動かない」를 씁니다. 集まる·始まる·合う는 기계가 작동하지 않는다는 뜻으로 쓰지 않습니다."},{"part":"言い換え","q":"わたしは <u>たいてい<\/u> 七時ごろ 起きます。","choices":["わたしは ほとんど いつも 七時ごろ 起きます。","わたしは かならず 七時ごろ 起きます。","わたしは ときどき 七時ごろ 起きます。","わたしは たまに 七時ごろ 起きます。"],"a":0,"ex":"たいてい는 '대개, 거의 늘'. かならず(반드시)는 예외가 없다는 뜻이라 의미가 더 강합니다."},{"part":"言い換え","q":"兄は 車の <u>工場<\/u>で 働いて います。","choices":["兄は 車を 洗う ところで 働いて います。","兄は 車を 売る ところで 働いて います。","兄は 車を 作る ところで 働いて います。","兄は 車を かす ところで 働いて います。"],"a":2,"ex":"工場은 물건을 만드는 곳입니다. 파는 곳은 店, 빌려주는 곳은 レンタカー店 등입니다."},{"part":"用法","q":"「安心」の 使い方として いちばん いいものを えらんでください。","choices":["わたしの 安心は 本を 読む ことです。","この 道は 車が 多くて 安心です。","あしたは 試験なので、とても 安心です。","母の 病気が よく なったと 聞いて、安心しました。"],"a":3,"ex":"安心은 걱정이 사라졌을 때 씁니다. 시험 전날이나 차가 많은 길은 오히려 걱정되는 상황이라 맞지 않습니다."},{"part":"用法","q":"「特別」の 使い方として いちばん いいものを えらんでください。","choices":["たんじょうびには 特別な ケーキを 作ります。","この ペンは 特別して 使って ください。","毎日 特別に 学校へ 行きます。","先生に 特別を もらいました。"],"a":0,"ex":"特別는 '보통과 다른'이라는 뜻의 な형용사입니다. '매일'과 함께 쓰면 모순이고, 特別を もらう·特別する는 틀린 형태입니다."}],"shadow":{"jp":"試験の 前に、もう 一度 たんごを ふくしゅうします。","r":"しけんの まえに、もう いちど たんごを ふくしゅうします。","ko":"시험 전에 한 번 더 단어를 복습합니다.","au":"7cde65393242"}},{"day":1,"title":"모의① 문법 20문제","vocab":[{"w":"集める","r":"あつめる","m":"모으다","au":"3506659aca85","rep":1},{"w":"送る","r":"おくる","m":"보내다, 바래다주다","au":"0586d36aa2d5","rep":1},{"w":"借りる","r":"かりる","m":"빌리다","au":"7959725c83b8","rep":1},{"w":"貸す","r":"かす","m":"빌려주다","au":"05322eca6540","rep":1},{"w":"返す","r":"かえす","m":"돌려주다","au":"667149264480","rep":1},{"w":"働く","r":"はたらく","m":"일하다","au":"1f0dd3cc4890","rep":1},{"w":"動く","r":"うごく","m":"움직이다, 작동하다","au":"9957acb248cd","rep":1},{"w":"始める","r":"はじめる","m":"시작하다","au":"4cb0cbefbe08","rep":1},{"w":"決める","r":"きめる","m":"정하다","au":"0081a418245b","rep":1},{"w":"間に合う","r":"まにあう","m":"(시간에) 늦지 않다, 대다","au":"665ac851fb17","rep":1},{"w":"遅れる","r":"おくれる","m":"늦다","au":"528fe6344b01","rep":1},{"w":"れんらくする","r":"れんらくする","m":"연락하다","au":"e0a6de326f06"},{"w":"じゅんびする","r":"じゅんびする","m":"준비하다","au":"2fac7e7a0de1"},{"w":"運ぶ","r":"はこぶ","m":"나르다, 옮기다","au":"cf2e3b1654d1","rep":1},{"w":"かたづける","r":"かたづける","m":"정리하다, 치우다","au":"626ae658bf6f"}],"lesson":{"summary":"실제 시험은 '언어지식(문법)·독해'를 55분 안에 함께 풉니다. 문법 20문제를 15~20분 안에 끝내는 연습을 합니다.","points":["문법(약 21문제)은 20분 안에 끝내고 독해에 35분 이상 남기는 것이 목표입니다. 문법에서 오래 고민하면 독해 시간이 모자랍니다.","文法形式: 빈칸 앞(동사 형태)과 문장 끝을 먼저 보고, 접속이 안 맞는 보기부터 지웁니다. 예: ～ために는 의지동사, ～ように는 가능형·무의지동사 뒤.","組み立て: 확실히 붙는 두 조각(명사+조사, 동사+かどうか 등)을 먼저 짝짓고 전체 순서를 정한 뒤 ★ 자리만 확인합니다. 빈칸 밑에 번호를 적어 두면 실수가 줄어듭니다.","文章の文法: 빈칸 앞뒤 한 문장씩 읽습니다. 접속사는 앞뒤 관계(반대=でも, 결과=それで, 추가=それに)로, 문말은 주어와 시제로 판단합니다.","수수·수동·사역·경어 문제는 먼저 '누가 누구에게'를 표시하세요. 주어만 정확히 잡아도 보기 두 개가 지워집니다."],"table":{"head":["유형","실제 문항(약)","목표 시간"],"rows":[["文法形式","13","1문제 30~40초 (약 8분)"],["組み立て","4","1문제 1분 (약 4분)"],["文章の文法","4","1문제 1분 (약 4분)"],["독해","8","남은 35분 이상"]]},"examples":[{"jp":"わたしは 先生が 書いた 本を 拝見しました。","r":"わたしは せんせいが かいた ほんを はいけんしました。","ko":"저는 선생님이 쓰신 책을 보았습니다(겸양).","au":"3740d5ef1a18"},{"jp":"駅に 着いたら、電話して ください。","r":"えきに ついたら、でんわして ください。","ko":"역에 도착하면 전화해 주세요.","au":"91e5ee0e88cd"},{"jp":"日本語が 話せるように、毎日 れんしゅうして います。","r":"にほんごが はなせるように、まいにち れんしゅうして います。","ko":"일본어를 말할 수 있도록 매일 연습하고 있습니다.","au":"7a9c1fa5d415"},{"jp":"子どもの ころ、母に 野菜を 食べさせられました。","r":"こどもの ころ、ははに やさいを たべさせられました。","ko":"어릴 때 엄마가 (억지로) 채소를 먹게 했습니다.","au":"5e778dacfd4c"}]},"drills":[{"part":"文法形式","q":"この ケーキは 母（　　）作って もらいました。","choices":["を","に","で","が"],"a":1,"ex":"「(사람)に ～て もらう」로 '그 사람이 해 주다'를 나타냅니다. 「母が 作って もらいました」는 주어가 틀립니다."},{"part":"文法形式","q":"この 店は 高いので、どんなに（　　）、わたしは 買いません。","choices":["ほしければ","ほしいと","ほしいなら","ほしくても"],"a":3,"ex":"「どんなに ～ても」는 '아무리 ~해도'. どんなに가 있으면 ても가 짝입니다."},{"part":"文法形式","q":"わたしは 先生が 書いた 本を（　　）。","choices":["拝見しました","見て くださいました","ご覧に なりました","お見に なりました"],"a":0,"ex":"주어가 わたし이므로 겸양어 拝見する. ご覧に なる는 윗사람의 행동에 쓰는 존경어이고, お見に なる라는 형태는 없습니다."},{"part":"文法形式","q":"社長は もう お帰りに（　　）。","choices":["いたしました","なりました","しました","まいりました"],"a":1,"ex":"「お＋ます형＋に なる」는 존경 표현입니다. 「お～する/いたす」는 나의 행동을 낮추는 겸양 표현이라 社長에게 쓸 수 없습니다."},{"part":"文法形式","q":"子どもの ころ、きらいな 野菜を 母に 毎日（　　）。とても いやでした。","choices":["食べさせられました","食べられました","食べさせました","食べて もらいました"],"a":0,"ex":"싫은데 억지로 한 일은 사역수동(～させられる)입니다. 食べられました는 '엄마가 먹어 버렸다'는 뜻이 되어 「いやでした」와 맞지 않습니다."},{"part":"文法形式","q":"駅に（　　）、電話して ください。","choices":["着くと","着いたら","着けば","着いても"],"a":1,"ex":"뒤에 부탁(～て ください)이 오면 たら를 씁니다. と는 뒤에 의뢰·의지가 올 수 없고, ば도 동작동사 뒤에서는 부탁과 함께 쓰기 어렵습니다."},{"part":"文法形式","q":"わたしは 友だちに たんじょうびの プレゼントを（　　）。","choices":["くださいました","もらいました","もらわれました","くれました"],"a":1,"ex":"「わたしは (사람)に ～を もらう」. くれる·くださる는 주어가 주는 사람(友だち)일 때 씁니다."},{"part":"文法形式","q":"日本語が 上手に 話せる（　　）、毎日 れんしゅうして います。","choices":["そうに","ことに","ように","ために"],"a":2,"ex":"가능형(話せる) 뒤에서 목적을 나타낼 때는 ように. ために는 의지동사(話す, 勉強する 등) 뒤에 씁니다."},{"part":"文法形式","q":"先週 買った（　　）の パソコンが もう こわれて しまいました。","choices":["あいだ","ところ","ばかり","まま"],"a":2,"ex":"「～た ばかり」는 '~한 지 얼마 안 된'으로 명사를 꾸밀 수 있습니다(買った ばかりの パソコン). 「～た ところ」는 명사 수식으로 쓰지 않습니다."},{"part":"文法形式","q":"あしたの パーティーに 行く（　　）、まだ きめて いません。","choices":["かどうか","ことに","ように","のに"],"a":0,"ex":"'갈지 안 갈지 아직 정하지 않았다'는 간접의문 「～かどうか」입니다."},{"part":"文法形式","q":"天気よほうに よると、あしたは ゆきが（　　）。","choices":["ふるように します","ふって あります","ふるそうです","ふりそうです"],"a":2,"ex":"「～に よると」는 전해 들은 말(전문)이므로 「사전형＋そうだ」. ふりそうです(양태)는 눈으로 보고 판단할 때 씁니다."},{"part":"文法形式","q":"まどが 開けて（　　）。だれが 開けたのでしょうか。","choices":["います","おきます","あります","しまいます"],"a":2,"ex":"타동사(開ける)＋て ある는 '누군가 해 놓은 상태'. 「まどが 開けて いる」는 문법적으로 틀립니다."},{"part":"文法形式","q":"道が こんで いたので、かいぎに（　　）。","choices":["おくれて みました","おくれて しまいました","おくれて あげました","おくれて おきました"],"a":1,"ex":"원하지 않은 결과에는 「～て しまう」. ～て おく(미리 해 두다)·～て みる(시도)는 의미가 맞지 않습니다."},{"part":"組み立て","q":"母に ＿＿ ＿＿ <b>★<\/b> ＿＿ わすれて しまいました。","choices":["買う","たのまれた","物を","のを"],"a":0,"ex":"완성: 母に たのまれた 物を 買う のを わすれて しまいました. ★에는 「買う」. '엄마가 부탁한 물건을 사는 것을 잊었다'."},{"part":"組み立て","q":"A「来週の 旅行、行けますか。」<br>B「すみません。仕事が ＿＿ ＿＿ <b>★<\/b> ＿＿ わかりません。」","choices":["かどうか","ので","いそがしい","行ける"],"a":3,"ex":"완성: 仕事が いそがしい ので 行ける かどうか わかりません. ★에는 「行ける」. 「～かどうか わからない」 짝을 먼저 찾으면 쉽습니다."},{"part":"組み立て","q":"かぜを ＿＿ ＿＿ <b>★<\/b> ＿＿ 洗って います。","choices":["ように","ひかない","家に 帰ったら","手を"],"a":2,"ex":"완성: かぜを ひかない ように 家に 帰ったら 手を 洗って います. ★에는 「家に 帰ったら」. 手を는 洗って 바로 앞에 와야 합니다."},{"part":"組み立て","q":"A「その ケーキ、おいしそうですね。」<br>B「これは 姉が わたしの ＿＿ ＿＿ <b>★<\/b> ＿＿ です。」","choices":["たんじょうびに","作って","ケーキ","くれた"],"a":3,"ex":"완성: 姉が わたしの たんじょうびに 作って くれた ケーキです. ★에는 「くれた」. わたしの 바로 뒤에는 명사(たんじょうび)가 옵니다."},{"part":"文章の文法","q":"わたしは 去年の 春に 日本へ 来ました。来た ばかりの ころは 日本語が あまり わからなくて、買い物も たいへんでした。<b>[ 1 ]<\/b>、近所の 人たちが とても 親切に して くれました。となりの 山田さんは、駅の 近くの 安い スーパーを わたしに [ 2 ]。今では 日本語で 話すのが 楽しく なりました。これからも 日本語の 勉強を つづけて、いつか 日本の 会社で [ 3 ] と 思って います。<br><br>[ 1 ]に 入る ものは どれですか。","choices":["でも","だから","それに","それで"],"a":0,"ex":"앞은 '쇼핑도 힘들었다', 뒤는 '이웃이 친절했다'로 내용이 반대이므로 でも. それに는 추가, だから·それで는 결과를 나타냅니다."},{"part":"文章の文法","q":"わたしは 去年の 春に 日本へ 来ました。来た ばかりの ころは 日本語が あまり わからなくて、買い物も たいへんでした。[ 1 ]、近所の 人たちが とても 親切に して くれました。となりの 山田さんは、駅の 近くの 安い スーパーを わたしに <b>[ 2 ]<\/b>。今では 日本語で 話すのが 楽しく なりました。これからも 日本語の 勉強を つづけて、いつか 日本の 会社で [ 3 ] と 思って います。<br><br>[ 2 ]に 入る ものは どれですか。","choices":["教えて あげました","教えて もらいました","教えさせました","教えて くれました"],"a":3,"ex":"주어 山田さん이 글쓴이(わたし)에게 해 준 일이므로 「～て くれました」. もらいました는 山田さん이 받은 사람이 되어 틀립니다."},{"part":"文章の文法","q":"わたしは 去年の 春に 日本へ 来ました。来た ばかりの ころは 日本語が あまり わからなくて、買い物も たいへんでした。[ 1 ]、近所の 人たちが とても 親切に して くれました。となりの 山田さんは、駅の 近くの 安い スーパーを わたしに [ 2 ]。今では 日本語で 話すのが 楽しく なりました。これからも 日本語の 勉強を つづけて、いつか 日本の 会社で <b>[ 3 ]<\/b> と 思って います。<br><br>[ 3 ]に 入る ものは どれですか。","choices":["働いた ばかり","働きそう","働く ため","働こう"],"a":3,"ex":"「의지형＋と 思って いる」로 계획을 나타냅니다. '언젠가 일하려고 생각하고 있다'."}],"shadow":{"jp":"上手に 話せるように、毎日 れんしゅうして います。","r":"じょうずに はなせるように、まいにち れんしゅうして います。","ko":"잘 말할 수 있도록 매일 연습하고 있습니다.","au":"4cf26f7425c0"}},{"day":2,"title":"모의① 독해 20문제","vocab":[{"w":"便利","r":"べんり","m":"편리하다","au":"9e4e6d178b25"},{"w":"不便","r":"ふべん","m":"불편하다","au":"dfc9bc1b5e94"},{"w":"親切","r":"しんせつ","m":"친절하다","au":"97945860f2a4","rep":1},{"w":"大切","r":"たいせつ","m":"소중하다","au":"f62d00a0638f","rep":1},{"w":"重い","r":"おもい","m":"무겁다","au":"828a2845e9a6","rep":1},{"w":"軽い","r":"かるい","m":"가볍다","au":"b01d0320fbf4","rep":1},{"w":"暗い","r":"くらい","m":"어둡다","au":"9f3b9b0f3312","rep":1},{"w":"うれしい","r":"うれしい","m":"기쁘다","au":"8f5bdfe353ed","rep":1},{"w":"さびしい","r":"さびしい","m":"쓸쓸하다, 외롭다","au":"c109847307c7","rep":1},{"w":"ひどい","r":"ひどい","m":"심하다, 지독하다","au":"8f3039b1ee10","rep":1},{"w":"ちょうど","r":"ちょうど","m":"딱, 정확히","au":"14289b04c924","rep":1},{"w":"たいてい","r":"たいてい","m":"대개","au":"1abc2fce27df"},{"w":"ぜひ","r":"ぜひ","m":"꼭(희망·권유)","au":"0c0ae74fce31","rep":1},{"w":"なかなか","r":"なかなか","m":"좀처럼(＋부정), 꽤","au":"a32883ca1d5c"},{"w":"きっと","r":"きっと","m":"분명히, 틀림없이","au":"3cb2d6fe403b"}],"lesson":{"summary":"독해 20문제(短文 6·中文 8·情報検索 6)를 풉니다. 질문을 먼저 읽고, 답이 있는 곳을 찾아가는 순서를 연습합니다.","points":["실제 시험 독해는 短文 3·中文 3·情報検索 2문제 정도이며, 문법을 끝내고 남은 약 35분을 씁니다.","어떤 유형이든 질문을 먼저 읽고 무엇을 찾는지(누가·언제·무엇을·왜)에 밑줄을 그은 뒤 본문을 읽습니다.","短文(메모·메일·안내): 「～て ください」「～なければ なりません」「～て おいて ください」 같은 지시 표현 근처에 답이 있습니다. 1문제 3분.","中文: 「でも」「ところが」 뒤에 글쓴이의 진짜 생각이 나옵니다. 이유를 묻는 질문은 「～から」「～ので」 부분을 찾으세요. 1지문(2문제) 8분.","情報検索: 표를 처음부터 다 읽지 말고, 질문의 조건(요일·시간·나이·가격)을 하나씩 대어 보며 지웁니다. ※ 표시된 주의 사항이 가장 흔한 함정입니다.","본문의 단어를 그대로 옮긴 보기가 오답인 경우가 많습니다. 단어가 아니라 의미가 같은지 확인하세요."],"table":{"head":["유형","지문 길이","실제 문항(약)","목표 시간"],"rows":[["短文","100~200자","3","1문제 3분"],["中文","350자 안팎","3 (지문 1개)","1지문 8분"],["情報検索","표·안내문","2","1문제 3분"]]},"examples":[{"jp":"しりょうを コピーして おいて ください。","r":"しりょうを コピーして おいて ください。","ko":"자료를 복사해 두세요.","au":"bb269284f261"},{"jp":"雨の 場合は、日曜日に します。","r":"あめの ばあいは、にちようびに します。","ko":"비가 올 경우에는 일요일에 합니다.","au":"28d16c1d4fd1"},{"jp":"駅から 遠くて 不便でしたが、今は べんりに なりました。","r":"えきから とおくて ふべんでしたが、いまは べんりに なりました。","ko":"역에서 멀어 불편했지만 지금은 편리해졌습니다.","au":"73f71bd56b17"}]},"drills":[{"part":"短文","q":"（会社で）<br>リンさんへ<br>午後 三時に 山田さんから 電話が ありました。あしたの かいぎの 時間が 十時から 十一時に かわったそうです。しりょうは 二十部 コピーして おいて ください。山田さんは あしたの 朝 九時ごろ 会社に 来るので、その 前に かいぎしつの じゅんびも して おいて ください。<br>中村<br><br>リンさんは あしたの かいぎの 前に 何を しなければ なりませんか。","choices":["しりょうを 十部 コピーして、山田さんに わたす。","九時に かいぎしつで 山田さんを 待つ。","山田さんに 電話して、かいぎの 時間を 聞く。","しりょうを コピーして、かいぎしつの じゅんびを する。"],"a":3,"ex":"메모의 지시 표현 「コピーして おいて ください」「じゅんびも して おいて ください」가 할 일입니다. 시간은 이미 전해 들었으므로 전화할 필요가 없습니다."},{"part":"短文","q":"＜図書館からの お知らせ＞<br>来月 一日から 十日まで、図書館の 中を きれいに する ため、本を 借りる ことが できません。かえす 本は 入り口の 前の はこに 入れて ください。二階の 学習室は いつもどおり 使えます。十一日からは、また 本を 借りる ことが できます。<br><br>来月 五日に 図書館で できる ことは 何ですか。","choices":["うけつけで 本を かえす こと","入り口の 前で 本を 借りる こと","二階の 学習室で 勉強する こと","本を 借りる こと"],"a":2,"ex":"1일~10일은 책을 빌릴 수 없고, 반납은 입구 앞 상자에 넣어야 합니다. 2층 학습실은 「いつもどおり 使えます」."},{"part":"短文","q":"マリアさん<br>来週の 土曜日の バーベキューですが、天気よほうでは 雨が ふるそうです。雨の 場合は、日曜日に します。日曜日も 雨だったら、つぎの 週の 土曜日に します。土曜日の 朝 八時に メールで れんらくしますから、見て ください。<br>ゆき<br><br>土曜日も 日曜日も 雨だったら、バーベキューは いつ しますか。","choices":["つぎの 週の 日曜日","来週の 土曜日","日曜日","つぎの 週の 土曜日"],"a":3,"ex":"「日曜日も 雨だったら、つぎの 週の 土曜日に します」. 来週の 土曜日는 원래 날짜라 함정입니다."},{"part":"短文","q":"（店の 入り口に はって ある 紙）<br>いつも ありがとうございます。<br>店の 中の 工事の ため、三月十五日（月）から 二十日（土）まで、午後 三時で 店を しめます。二十一日（日）は 休みです。二十二日（月）からは、いつもどおり 午前十時から 午後八時まで 開いて います。<br><br>三月十八日に この 店で 買い物を したいです。何時までに 行けば いいですか。","choices":["午後 三時","午前 十時","午後 八時","この 日は 休みなので 行けない"],"a":0,"ex":"18일은 15일~20일 사이이므로 오후 3시에 문을 닫습니다. 쉬는 날은 21일입니다."},{"part":"短文","q":"ケンへ<br>お母さんは 今日 友だちと 出かけます。夜 七時ごろ 帰ります。ばんごはんは れいぞうこに カレーが あるので、あたためて 食べて ください。それから、四時ごろ おばあちゃんから にもつが とどきます。うけとったら、おばあちゃんに おれいの 電話を して ください。<br>母<br><br>ケンさんは にもつが とどいたら、何を しますか。","choices":["お母さんに 電話を する。","おばあちゃんの 家に にもつを 送る。","おばあちゃんに 電話を する。","カレーを あたためて 食べる。"],"a":2,"ex":"「うけとったら、おばあちゃんに おれいの 電話を して ください」. 카레는 저녁에 할 일이라 질문과 다릅니다."},{"part":"短文","q":"＜日本語クラスの みなさんへ＞<br>来週の 水曜日、クラスで 近くの おてらへ 行きます。朝 九時に 学校の 前に 集まって ください。おてらまでは 歩いて 二十分 ぐらいです。お昼ごはんは おてらの 近くの 店で みんなで 食べるので、持って 来なくても いいです。でも、飲み物は 自分で 持って 来て ください。<br><br>水曜日に 学生が 持って 行かなければ ならない ものは 何ですか。","choices":["お昼ごはん","何も 持って 行かなくても いい","飲み物","飲み物と お昼ごはん"],"a":2,"ex":"점심은 가게에서 먹으므로 「持って 来なくても いい」, 음료는 「自分で 持って 来て ください」. でも 뒤가 핵심입니다."},{"part":"中文","q":"先月、わたしは 大学の 近くの アパートに ひっこしました。前の アパートは 駅から 遠くて、大学まで 一時間も かかりました。新しい アパートからは 歩いて 十分で 行けるので、朝 ゆっくり ねられるように なりました。<br>でも、こまった ことも あります。新しい アパートの 近くには スーパーが ありません。いちばん 近い スーパーまで 自転車で 十五分 かかります。前の アパートは 駅の 前に 大きな スーパーが あったので、買い物は とても べんりでした。今は 一週間に 一回、土曜日に たくさん 買い物を して います。<br>先週、となりの 部屋の 田中さんに この 話を したら、「インターネットで 買い物を すると、家まで とどけて くれますよ。」と 教えて くれました。重い 物を 運ばなくても いいので、来週から ためして みようと 思います。<br><br>新しい アパートの よい ところは 何ですか。","choices":["大学まで 近くて、朝 ゆっくり できる こと","駅の 前に 大きな スーパーが ある こと","スーパーまで 自転車で すぐ 行ける こと","となりの 人が 買い物を して くれる こと"],"a":0,"ex":"걸어서 10분이라 아침에 여유 있게 잘 수 있게 되었습니다. 역 앞 큰 슈퍼는 예전 아파트 이야기입니다."},{"part":"中文","q":"先月、わたしは 大学の 近くの アパートに ひっこしました。前の アパートは 駅から 遠くて、大学まで 一時間も かかりました。新しい アパートからは 歩いて 十分で 行けるので、朝 ゆっくり ねられるように なりました。<br>でも、こまった ことも あります。新しい アパートの 近くには スーパーが ありません。いちばん 近い スーパーまで 自転車で 十五分 かかります。前の アパートは 駅の 前に 大きな スーパーが あったので、買い物は とても べんりでした。今は 一週間に 一回、土曜日に たくさん 買い物を して います。<br>先週、となりの 部屋の 田中さんに この 話を したら、「インターネットで 買い物を すると、家まで とどけて くれますよ。」と 教えて くれました。重い 物を 運ばなくても いいので、来週から ためして みようと 思います。<br><br>この 人は 来週から 何を しようと 思って いますか。","choices":["田中さんと いっしょに 買い物に 行く。","駅の 前の スーパーで 買い物を する。","インターネットで 買い物を する。","土曜日に 自転車で スーパーへ 行く。"],"a":2,"ex":"마지막 문장 「来週から ためして みようと 思います」의 대상은 앞 문장의 인터넷 쇼핑입니다."},{"part":"中文","q":"わたしが 日本に 来て、いちばん おどろいたのは ごみの 出し方です。わたしの 国では、ごみを ぜんぶ 一つの ふくろに 入れて 出します。でも、日本では もえる ごみ、もえない ごみ、びんや かんなどに 分けて、きめられた 曜日に 出さなければ なりません。<br>はじめの ころ、わたしは 曜日を まちがえて、ごみを 出して しまいました。つぎの 日、アパートの かんりにんさんに 注意されました。とても はずかしかったです。<br>それから、わたしは ごみの カレンダーを れいぞうこに はって、毎朝 見るように しました。今では まちがえなく なりました。分けるのは 少し たいへんですが、ごみを 分けると、また 使える 物が 多く なると 聞きました。今は いい しゅうかんだと 思って います。<br><br>この 人は どうして はずかしかったのですか。","choices":["かんりにんさんと 日本語で 話せなかったから","ごみを 一つの ふくろに 入れて 出したから","ちがう 曜日に ごみを 出して、注意されたから","ごみの カレンダーを なくして しまったから"],"a":2,"ex":"요일을 착각해 쓰레기를 내놓았고 다음 날 관리인에게 주의를 받았습니다. 한 봉투에 넣는 것은 자기 나라 이야기입니다."},{"part":"中文","q":"わたしが 日本に 来て、いちばん おどろいたのは ごみの 出し方です。わたしの 国では、ごみを ぜんぶ 一つの ふくろに 入れて 出します。でも、日本では もえる ごみ、もえない ごみ、びんや かんなどに 分けて、きめられた 曜日に 出さなければ なりません。<br>はじめの ころ、わたしは 曜日を まちがえて、ごみを 出して しまいました。つぎの 日、アパートの かんりにんさんに 注意されました。とても はずかしかったです。<br>それから、わたしは ごみの カレンダーを れいぞうこに はって、毎朝 見るように しました。今では まちがえなく なりました。分けるのは 少し たいへんですが、ごみを 分けると、また 使える 物が 多く なると 聞きました。今は いい しゅうかんだと 思って います。<br><br>この 人は 今、ごみの 分け方に ついて どう 思って いますか。","choices":["たいへんだが、いい しゅうかんだ。","たいへんなので、やめたい。","自分の 国の やり方の ほうが いい。","かんたんで、とても いい。"],"a":0,"ex":"「分けるのは 少し たいへんですが … いい しゅうかんだと 思って います」. が(でも) 뒤가 글쓴이의 생각입니다."},{"part":"中文","q":"わたしは 毎週 金曜日と 土曜日に、駅の 近くの パン屋で アルバイトを して います。店長は とても きびしい 人で、はじめの 一か月は 毎日のように しかられました。パンの 名前を おぼえるのが おそかったり、おきゃくさんへの あいさつの 声が 小さかったり したからです。<br>ある 日、わたしは 店長に「もう やめたいです。」と 言いました。すると 店長は「あなたは まじめだから、きっと できるように なるよ。」と 言って くれました。その 日から、わたしは 家で パンの 名前を 書いて おぼえたり、大きな 声で あいさつの れんしゅうを したり しました。<br>今では、おきゃくさんに「いつも 元気ですね。」と 言われるように なりました。先週は 店長に ほめられました。あの とき やめないで、ほんとうに よかったと 思います。<br><br>この 人は どうして 店長に しかられましたか。","choices":["店長に やめたいと 言ったから","パンの 名前を おぼえるのが おそくて、あいさつの 声も 小さかったから","アルバイトに よく おくれて 来たから","おきゃくさんに 元気が ないと 言われたから"],"a":1,"ex":"「～たり ～たり したからです」 부분이 이유입니다. 지각 이야기는 나오지 않습니다."},{"part":"中文","q":"わたしは 毎週 金曜日と 土曜日に、駅の 近くの パン屋で アルバイトを して います。店長は とても きびしい 人で、はじめの 一か月は 毎日のように しかられました。パンの 名前を おぼえるのが おそかったり、おきゃくさんへの あいさつの 声が 小さかったり したからです。<br>ある 日、わたしは 店長に「もう やめたいです。」と 言いました。すると 店長は「あなたは まじめだから、きっと できるように なるよ。」と 言って くれました。その 日から、わたしは 家で パンの 名前を 書いて おぼえたり、大きな 声で あいさつの れんしゅうを したり しました。<br>今では、おきゃくさんに「いつも 元気ですね。」と 言われるように なりました。先週は 店長に ほめられました。あの とき やめないで、ほんとうに よかったと 思います。<br><br>この 人が「ほんとうに よかった」と 思うのは どうしてですか。","choices":["店長が やさしい 人に なったから","アルバイトを やめて、勉強が できたから","パンを 安く 買えるように なったから","やめないで がんばったら、できるように なったから"],"a":3,"ex":"그만두지 않고 연습해서 손님에게 칭찬받고 점장에게도 칭찬받게 되었기 때문입니다."},{"part":"中文","q":"このごろ、手紙を 書く 人は 少なく なりました。メールなら すぐ 送れるし、お金も かからないからです。わたしも ふだんは メールを 使って います。<br>でも 先月、わたしは 入院して いる そぼに 手紙を 書きました。そぼは 目が 悪くて、スマートフォンの 小さい 字が 読めないからです。大きな 字で、学校の ことや 家族の ことを 書いて 送りました。<br>一週間後、そぼから へんじが 来ました。少し ふるえた 字で「手紙を 何度も 読んで います。早く 元気に なって、あなたに 会いたいです。」と 書いて ありました。わたしは うれしくて、なみだが 出ました。手紙は 時間が かかりますが、書いた 人の 気持ちが よく つたわると 思いました。これからも ときどき そぼに 手紙を 書こうと 思います。<br><br>この 人は どうして メールでは なく 手紙を 書きましたか。","choices":["そぼが 手紙が ほしいと 言ったから","メールは お金が かかるから","手紙の ほうが 早く とどくから","そぼが スマートフォンの 小さい 字を 読めないから"],"a":3,"ex":"「そぼは 目が 悪くて、スマートフォンの 小さい 字が 読めないからです」. 메일이 돈이 든다는 말은 반대입니다."},{"part":"中文","q":"このごろ、手紙を 書く 人は 少なく なりました。メールなら すぐ 送れるし、お金も かからないからです。わたしも ふだんは メールを 使って います。<br>でも 先月、わたしは 入院して いる そぼに 手紙を 書きました。そぼは 目が 悪くて、スマートフォンの 小さい 字が 読めないからです。大きな 字で、学校の ことや 家族の ことを 書いて 送りました。<br>一週間後、そぼから へんじが 来ました。少し ふるえた 字で「手紙を 何度も 読んで います。早く 元気に なって、あなたに 会いたいです。」と 書いて ありました。わたしは うれしくて、なみだが 出ました。手紙は 時間が かかりますが、書いた 人の 気持ちが よく つたわると 思いました。これからも ときどき そぼに 手紙を 書こうと 思います。<br><br>そぼからの へんじを 読んで、この 人は どう 思いましたか。","choices":["手紙は 時間が かかるので、もう 書かない。","手紙は 書いた 人の 気持ちが よく つたわる。","そぼの 字が 読めなくて、こまった。","これからは メールだけ 使おう。"],"a":1,"ex":"「手紙は 時間が かかりますが、書いた 人の 気持ちが よく つたわる」. が 뒤가 핵심이고, 앞으로도 편지를 쓰겠다고 했습니다."},{"part":"情報検索","q":"＜さくら市 市民センター 料理教室＞<br>① 日本の 家の 料理　月曜日 午前10時〜12時　1回 1,500円<br>② パンを 作ろう　水曜日 午後2時〜4時　1回 1,200円<br>③ おべんとう 教室　土曜日 午前10時〜12時　1回 1,000円<br>④ 子どもと いっしょに おかし作り　日曜日 午後1時〜3時　親子 二人で 1回 2,000円<br>※ どの 教室も、もうしこみは 一週間前までに 電話で して ください。<br><br>キムさんは 会社員で、月曜日から 金曜日まで 毎日 午前9時から 午後6時まで 働いて います。一人で 料理教室に 行きたいです。キムさんが 行ける 教室は どれですか。","choices":["③ おべんとう 教室","④ 子どもと いっしょに おかし作り","① 日本の 家の 料理","② パンを 作ろう"],"a":0,"ex":"평일 낮은 일하므로 주말 교실만 가능합니다. ④는 일요일이지만 부모와 아이가 함께 가는 교실이라 혼자 갈 수 없습니다."},{"part":"情報検索","q":"＜さくら市 市民センター 料理教室＞<br>① 日本の 家の 料理　月曜日 午前10時〜12時　1回 1,500円<br>② パンを 作ろう　水曜日 午後2時〜4時　1回 1,200円<br>③ おべんとう 教室　土曜日 午前10時〜12時　1回 1,000円<br>④ 子どもと いっしょに おかし作り　日曜日 午後1時〜3時　親子 二人で 1回 2,000円<br>※ どの 教室も、もうしこみは 一週間前までに 電話で して ください。<br><br>マリアさんは 日曜日に むすめ（十さい）と いっしょに 料理教室に 行きたいです。二人で いくら はらいますか。","choices":["3,000円","2,000円","4,000円","1,000円"],"a":1,"ex":"일요일 교실은 ④뿐이고 요금은 「親子 二人で 1回 2,000円」입니다. 한 사람당 2,000엔으로 계산하면 4,000엔이라는 함정에 걸립니다."},{"part":"情報検索","q":"＜みどり映画館　今週の 上映時間＞<br>「海の 歌」　① 10:00〜11:50　② 13:00〜14:50　③ 18:30〜20:20<br>「森の 犬」　① 9:30〜11:00　② 11:30〜13:00　③ 15:00〜16:30<br>「夜の 町」　① 12:00〜14:10　② 16:00〜18:10　③ 20:00〜22:10<br>料金：大人 1,800円 ／ 学生 1,500円 ／ 水曜日は だれでも 1,200円<br><br>山田さんは 土曜日の 午後1時に 駅で 友だちと 会います。駅から 映画館までは 10分 かかります。二人は 映画を 見た あと、午後5時から ばんごはんを 食べに 行きます。二人が 見る ことが できる 映画は どれですか。","choices":["「森の 犬」の ③","「夜の 町」の ②","「海の 歌」の ②","「森の 犬」の ②"],"a":0,"ex":"1시 10분 이후에 시작해서 5시 전에 끝나는 것은 「森の 犬」③(15:00~16:30)뿐입니다. 「海の 歌」②는 13:00 시작이라 늦습니다."},{"part":"情報検索","q":"＜みどり映画館　今週の 上映時間＞<br>「海の 歌」　① 10:00〜11:50　② 13:00〜14:50　③ 18:30〜20:20<br>「森の 犬」　① 9:30〜11:00　② 11:30〜13:00　③ 15:00〜16:30<br>「夜の 町」　① 12:00〜14:10　② 16:00〜18:10　③ 20:00〜22:10<br>料金：大人 1,800円 ／ 学生 1,500円 ／ 水曜日は だれでも 1,200円<br><br>大学生の リンさんは 水曜日に 一人で 映画を 見ます。いくら はらいますか。","choices":["2,700円","1,200円","1,500円","1,800円"],"a":1,"ex":"학생 요금은 1,500엔이지만 「水曜日は だれでも 1,200円」이 우선합니다."},{"part":"情報検索","q":"＜アルバイトの お知らせ＞<br>① 本屋　月・水・金　午後5時〜9時　一時間 1,100円　日本語が 読める 人<br>② レストラン　土・日　午前10時〜午後4時　一時間 1,200円　はじめての 人も だいじょうぶ<br>③ 花屋　火・木　午前9時〜午後1時　一時間 1,050円　車の 運転が できる 人<br>④ コンビニ　毎日（週 二日から だいじょうぶ）　午後10時〜午前6時　一時間 1,400円<br><br>チャンさんは 大学生で、日本語の 新聞も 読めます。月曜日から 金曜日までは 午前9時から 午後3時まで じゅぎょうが あり、土曜日と 日曜日は 家族の 店を てつだって います。夜 11時までには 家に 帰りたいです。車の 運転は できません。チャンさんが できる アルバイトは どれですか。","choices":["② レストラン","① 本屋","③ 花屋","④ コンビニ"],"a":1,"ex":"②는 주말이라 안 되고, ③은 수업 시간과 겹치며 운전이 필요하고, ④는 밤 10시부터라 늦습니다."},{"part":"情報検索","q":"＜アルバイトの お知らせ＞<br>① 本屋　月・水・金　午後5時〜9時　一時間 1,100円　日本語が 読める 人<br>② レストラン　土・日　午前10時〜午後4時　一時間 1,200円　はじめての 人も だいじょうぶ<br>③ 花屋　火・木　午前9時〜午後1時　一時間 1,050円　車の 運転が できる 人<br>④ コンビニ　毎日（週 二日から だいじょうぶ）　午後10時〜午前6時　一時間 1,400円<br><br>一時間に もらえる お金が いちばん 多い アルバイトは 何時に 始まりますか。","choices":["午前9時","午後5時","午前10時","午後10時"],"a":3,"ex":"시급이 가장 높은 것은 ④ 편의점(1,400엔)이고 오후 10시에 시작합니다."}],"shadow":{"jp":"質問を 先に 読んでから、本文を 読みます。","r":"しつもんを さきに よんでから、ほんぶんを よみます。","ko":"질문을 먼저 읽고 나서 본문을 읽습니다.","au":"90e365c632fc"}},{"day":3,"title":"모의① 청해 20문제","vocab":[{"w":"アルバイト","r":"アルバイト","m":"아르바이트","au":"1ade2f31c82e"},{"w":"レポート","r":"レポート","m":"리포트, 보고서","au":"66cf27bf8531"},{"w":"コピー","r":"コピー","m":"복사","au":"06c57130744b"},{"w":"チケット","r":"チケット","m":"티켓, 표","au":"bf86d11e4687"},{"w":"予約","r":"よやく","m":"예약","au":"7d5219d28345","rep":1},{"w":"受付","r":"うけつけ","m":"접수(처)","au":"1dfde7eab9c6","rep":1},{"w":"会議","r":"かいぎ","m":"회의","au":"6d410fe869f5","rep":1},{"w":"出席","r":"しゅっせき","m":"출석","au":"350c8046e7ec","rep":1},{"w":"欠席","r":"けっせき","m":"결석","au":"7bf2533759a1","rep":1},{"w":"都合","r":"つごう","m":"사정, 형편","au":"f8ce96e1297e","rep":1},{"w":"用意","r":"ようい","m":"준비, 마련","au":"b47b5bdda8eb","rep":1},{"w":"案内","r":"あんない","m":"안내","au":"c069f1ae5242","rep":1},{"w":"売り場","r":"うりば","m":"매장, 판매장","au":"80b766cd3fc5","rep":1},{"w":"工事","r":"こうじ","m":"공사","au":"70471c3b8398"},{"w":"戻る","r":"もどる","m":"돌아오다, 되돌아가다","au":"0ef823b6d246","rep":1}],"lesson":{"summary":"청해 20문제(課題理解 8·ポイント理解 7·発話表現 5)를 풉니다. 음성은 한 번만 나온다고 생각하고, 다시 듣지 말고 풀어 보세요.","points":["실제 청해는 35분, 課題理解 8·ポイント理解 7·発話表現 5·即時応答 8문제 정도입니다. 음성은 한 번만 나오고 중간에 멈출 수 없습니다.","課題理解: 질문이 먼저 나옵니다. 「まず」「このあと」가 있으면 '맨 처음 할 일'을 찾습니다. 대화 중 「その 前に」「それは もう しました」로 순서가 바뀌는 것이 함정입니다.","ポイント理解: 질문 뒤에 보기를 읽을 시간(약 20초)이 있습니다. 보기를 훑어보고 이유·시간·장소 중 무엇을 들을지 정하세요. 「でも」「いちばん」「やっぱり」 뒤가 답입니다.","発話表現: 그림 속 화살표 인물이 하는 말을 고릅니다. 내가 해 주는 말(～ましょうか)인지 부탁하는 말(～て いただけませんか)인지 구별하세요.","메모는 숫자·요일·물건 이름만 짧게. 한 문제를 놓쳐도 바로 다음 문제에 집중하는 것이 점수를 지키는 방법입니다."],"table":{"head":["유형","실제 문항(약)","들을 포인트"],"rows":[["課題理解","8","마지막에 정해진 할 일, 순서(まず)"],["ポイント理解","7","이유·시간·장소, でも/いちばん 뒤"],["発話表現","5","그림 속 상황, 누가 하는 행동인지"],["即時応答","8","짧은 말에 맞는 대답(금요일)"]]},"examples":[{"jp":"コピーの 前に、すうじを もう 一度 見て くれませんか。","r":"コピーの まえに、すうじを もう いちど みて くれませんか。","ko":"복사하기 전에 숫자를 한 번 더 봐 주시겠어요?","au":"57f87e14c7e7"},{"jp":"いちばんの りゆうは やっぱり 音です。","r":"いちばんの りゆうは やっぱり おとです。","ko":"가장 큰 이유는 역시 소리입니다.","au":"a6d35ab4d7c6"},{"jp":"先に 映画館に 行って、チケットを 買って おいて くれる？","r":"さきに えいがかんに いって、チケットを かって おいて くれる？","ko":"먼저 영화관에 가서 티켓을 사 둬 줄래?","au":"13c7de279804"},{"jp":"一つ お持ちしましょうか。","r":"ひとつ おもちしましょうか。","ko":"하나 들어 드릴까요?","au":"bc0c67620082"}]},"drills":[{"part":"課題理解","q":"女の人は このあと まず 何を しますか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話して います。女の人は このあと まず 何を しますか。"},{"s":"M","t":"田中さん、あしたの かいぎの しりょう、もう できましたか。"},{"s":"F","t":"はい、さっき できました。これから 二十部 コピーします。"},{"s":"M","t":"あ、コピーの 前に、三ページの すうじを もう 一度 見て くれませんか。先週の すうじが 入って いる ような 気が するんです。"},{"s":"F","t":"わかりました。すぐ 見ます。かいぎしつの よやくは きのう して おきました。"},{"s":"N","t":"女の人は このあと まず 何を しますか。"}],"choices":["しりょうの すうじを 見る","しりょうを コピーする","かいぎしつを よやくする","しりょうを 作る"],"a":0,"ex":"「コピーの 前に … すうじを もう 一度 見て くれませんか」. 복사는 그다음이고, 예약은 이미 끝났습니다.","au":"a1ea9ec447e4"},{"part":"課題理解","q":"男の 学生は 家に 帰ってから 何を しなければ なりませんか。","listen":[{"s":"N","t":"学校で 先生と 男の 学生が 話して います。男の 学生は 家に 帰ってから 何を しなければ なりませんか。"},{"s":"F","t":"木村さん、来週の はっぴょうの じゅんびは どうですか。"},{"s":"M","t":"はい、はっぴょうの げんこうは もう 書きました。"},{"s":"F","t":"そうですか。じゃあ、家で 声に 出して 読む れんしゅうを して ください。時間は 五分までですよ。"},{"s":"M","t":"はい。写真も 使いたいんですが。"},{"s":"F","t":"写真は あしたの じゅぎょうで いっしょに えらびましょう。"},{"s":"N","t":"男の 学生は 家に 帰ってから 何を しなければ なりませんか。"}],"choices":["はっぴょうの げんこうを 書く","先生に メールを 送る","使う 写真を えらぶ","声に 出して 読む れんしゅうを する"],"a":3,"ex":"원고는 이미 썼고, 사진은 내일 수업에서 함께 고릅니다. 집에서 할 일은 소리 내어 읽는 연습입니다.","au":"ba9abfc63ca1"},{"part":"課題理解","q":"男の人は これから 何を 買いに 行きますか。","listen":[{"s":"N","t":"家で 女の人と 男の人が 話して います。男の人は これから 何を 買いに 行きますか。"},{"s":"F","t":"あ、たまごが ない。ケーキを 作ろうと 思ったのに。"},{"s":"M","t":"じゃあ、ぼくが 買って くるよ。ほかに いる 物 ある？"},{"s":"F","t":"ぎゅうにゅうは まだ あるし。あ、さとうも 少ししか ないな。"},{"s":"M","t":"さとうなら、きのう たなの 上に 新しいのが あるのを 見たよ。"},{"s":"F","t":"よかった。じゃあ、たまごだけ おねがい。"},{"s":"N","t":"男の人は これから 何を 買いに 行きますか。"}],"choices":["さとう","たまごと ぎゅうにゅう","たまごと さとう","たまご"],"a":3,"ex":"설탕은 선반 위에 새것이 있고 우유도 남아 있습니다. 마지막 「たまごだけ おねがい」가 정답의 근거입니다.","au":"31ba4073c129"},{"part":"課題理解","q":"男の人は まず どの 電車に 乗りますか。","listen":[{"s":"N","t":"駅で 男の人と 駅の 人が 話して います。男の人は まず どの 電車に 乗りますか。"},{"s":"M","t":"すみません、みなと駅へ 行きたいんですが、つぎの 電車に 乗れば いいですか。"},{"s":"F","t":"つぎの 電車は 急行なので、みなと駅には 止まりません。かくえきていしゃは 十時十五分です。"},{"s":"M","t":"十時十五分ですか。少し 時間が ありますね。"},{"s":"F","t":"でも、急行で さくら駅まで 行って、そこで かくえきていしゃに 乗りかえた ほうが 早く 着きますよ。"},{"s":"M","t":"そうですか。じゃあ、そうします。"},{"s":"N","t":"男の人は まず どの 電車に 乗りますか。"}],"choices":["みなと駅まで 歩く","さくら駅から バスに 乗る","つぎの 急行に 乗る","十時十五分の かくえきていしゃに 乗る"],"a":2,"ex":"역무원이 급행으로 さくら駅까지 가서 갈아타는 편이 빠르다고 했고, 남자는 「そうします」라고 했습니다. 처음 타는 것은 급행입니다.","au":"5cc4f3674698"},{"part":"課題理解","q":"男の人は このあと まず 何を しますか。","listen":[{"s":"N","t":"病院の うけつけで 女の人と 男の人が 話して います。男の人は このあと まず 何を しますか。"},{"s":"F","t":"はじめてですか。では、この 紙に お名前と ご住所を 書いて ください。"},{"s":"M","t":"はい。ほけんしょうは どう しますか。"},{"s":"F","t":"ほけんしょうは、書いた 紙と いっしょに 出して ください。それから、ねつを はかって ください。"},{"s":"M","t":"ねつは 家で はかって きました。三十八度でした。"},{"s":"F","t":"そうですか。では、ねつは はからなくて いいですよ。"},{"s":"N","t":"男の人は このあと まず 何を しますか。"}],"choices":["ねつを はかる","ほけんしょうを 出す","紙に 名前と 住所を 書く","先生に 会う"],"a":2,"ex":"보험증은 다 쓴 종이와 함께 내라고 했으니 먼저 종이를 써야 합니다. 열은 집에서 이미 쟀습니다.","au":"651087368d51"},{"part":"課題理解","q":"女の人は このあと 何を しますか。","listen":[{"s":"N","t":"男の人と 女の人が 電話で 話して います。女の人は このあと 何を しますか。"},{"s":"M","t":"もしもし、ゆみさん？ 今日の 映画、六時に 駅で 会う やくそくだったけど、仕事が 終わらなくて。"},{"s":"F","t":"え、来られないの？"},{"s":"M","t":"行けるよ。でも 三十分 おくれそう。先に 映画館に 行って、チケットを 二まい 買って おいて くれる？"},{"s":"F","t":"いいよ。じゃあ、映画館の 前で 待ってるね。"},{"s":"N","t":"女の人は このあと 何を しますか。"}],"choices":["男の人の 会社へ 行く","映画館で チケットを 買う","駅で 六時半まで 待つ","映画を 一人で 見る"],"a":1,"ex":"남자가 먼저 영화관에 가서 티켓을 사 두라고 부탁했고 여자가 「いいよ」라고 답했습니다. 기다리는 곳은 역이 아니라 영화관 앞입니다.","au":"97f0b15c6ebd"},{"part":"課題理解","q":"男の人は これから 何を かばんに 入れますか。","listen":[{"s":"N","t":"会社で 女の人と 男の人が 話して います。男の人は これから 何を かばんに 入れますか。"},{"s":"F","t":"森さん、あしたの 名古屋の しゅっちょう、じゅんびは できた？"},{"s":"M","t":"はい。しりょうと パソコンは もう かばんに 入れました。"},{"s":"F","t":"名古屋は あした 雨らしいから、かさも 持って 行った ほうが いいよ。"},{"s":"M","t":"そうですか。小さい かさが あるので、それを 入れて おきます。"},{"s":"F","t":"それから、めいしも わすれないでね。"},{"s":"M","t":"めいしは いつも さいふに 入れて あるので、だいじょうぶです。"},{"s":"N","t":"男の人は これから 何を かばんに 入れますか。"}],"choices":["かさ","めいし","かさと めいし","しりょうと パソコン"],"a":0,"ex":"자료와 노트북은 이미 넣었고, 명함은 늘 지갑에 있습니다. 새로 넣을 것은 우산뿐입니다.","au":"d5efb326d12a"},{"part":"課題理解","q":"男の 学生は このあと 何を しますか。","listen":[{"s":"N","t":"図書館で 男の 学生と 図書館の 人が 話して います。男の 学生は このあと 何を しますか。"},{"s":"M","t":"すみません、この 本を 借りたいんですが。"},{"s":"F","t":"はい。がくせいしょうを 見せて ください。"},{"s":"M","t":"あ、今日 家に わすれて きて しまいました。"},{"s":"F","t":"がくせいしょうが ないと 借りられないんです。でも、コピーなら 二階で できますよ。"},{"s":"M","t":"そうですか。じゃあ、今日は ひつような ところだけ コピーして、借りるのは あしたに します。"},{"s":"N","t":"男の 学生は このあと 何を しますか。"}],"choices":["家に がくせいしょうを とりに 帰る","二階で 本を コピーする","本を 借りる","図書館の 人に がくせいしょうを 見せる"],"a":1,"ex":"학생증이 없어 오늘은 빌릴 수 없으니, 필요한 부분만 2층에서 복사하겠다고 했습니다.","au":"0b7a94e099eb"},{"part":"ポイント理解","q":"女の人が ひっこす いちばんの りゆうは 何ですか。","listen":[{"s":"N","t":"男の人と 女の人が 話して います。女の人が ひっこす いちばんの りゆうは 何ですか。"},{"s":"M","t":"林さん、来月 ひっこすんだって？ 今の アパート、駅から 近くて べんりだって 言って いたのに。"},{"s":"F","t":"うん。駅から 近いのは いいんだけど、となりの 部屋の 人が 夜 おそくまで うるさくて。"},{"s":"M","t":"そうか。それは たいへんだね。"},{"s":"F","t":"それに やちんも 高いしね。でも、いちばんの りゆうは やっぱり 音かな。"},{"s":"N","t":"女の人が ひっこす いちばんの りゆうは 何ですか。"}],"choices":["駅から 遠いから","となりの 部屋が うるさいから","部屋が せまいから","やちんが 高いから"],"a":1,"ex":"집세도 비싸지만 「いちばんの りゆうは やっぱり 音」. 역에서는 가까워서 편리하다고 했습니다.","au":"4dd719223983"},{"part":"ポイント理解","q":"女の人は 何日に 店へ 来ますか。","listen":[{"s":"N","t":"くつの 店で 女の人と 店の 人が 話して います。女の人は 何日に 店へ 来ますか。"},{"s":"F","t":"すみません、この くつの 二十四センチは ありますか。"},{"s":"M","t":"もうしわけ ございません。今 ないんです。来週の 月曜日、十日に 入りますが。"},{"s":"F","t":"十日ですか。その 日は 仕事で 来られないんです。"},{"s":"M","t":"では、とって おきますので、十日から 一週間の 間に とりに 来て いただけますか。"},{"s":"F","t":"わかりました。じゃあ、十二日の 水曜日に 来ます。"},{"s":"N","t":"女の人は 何日に 店へ 来ますか。"}],"choices":["十一日","十日","十二日","十七日"],"a":2,"ex":"물건은 10일에 들어오지만 그날은 일 때문에 못 오고, 마지막에 「十二日の 水曜日に 来ます」라고 했습니다.","au":"73d68f15e16e"},{"part":"ポイント理解","q":"車の かぎは どこに ありましたか。","listen":[{"s":"N","t":"家で 男の人と 女の人が 話して います。車の かぎは どこに ありましたか。"},{"s":"M","t":"ねえ、車の かぎ 知らない？ いつも げんかんの たなに おいて いるんだけど、ないんだ。"},{"s":"F","t":"きのうの コートの ポケットは？"},{"s":"M","t":"さっき 見たけど、なかった。かばんの 中にも ない。"},{"s":"F","t":"そう いえば、きのう 夜 帰って きた とき、台所の テーブルに おいて なかった？"},{"s":"M","t":"あ、あった。ありがとう。"},{"s":"N","t":"車の かぎは どこに ありましたか。"}],"choices":["かばんの 中","台所の テーブルの 上","げんかんの たな","コートの ポケット"],"a":1,"ex":"현관 선반·코트 주머니·가방은 모두 없었고, 부엌 테이블에서 「あった」라고 했습니다.","au":"f90a86ec6d5b"},{"part":"ポイント理解","q":"女の 学生は どうして おくれましたか。","listen":[{"s":"N","t":"学校で 先生と 女の 学生が 話して います。女の 学生は どうして おくれましたか。"},{"s":"M","t":"山田さん、今日は どうして おくれたんですか。また ねぼうですか。"},{"s":"F","t":"いいえ、今日は 早く 起きました。電車も おくれて いませんでした。"},{"s":"M","t":"じゃあ、どうして？"},{"s":"F","t":"駅で 道が わからない おばあさんが いて、いっしょに 病院まで 行ったんです。"},{"s":"M","t":"そうですか。それは いい ことを しましたね。"},{"s":"N","t":"女の 学生は どうして おくれましたか。"}],"choices":["おばあさんと いっしょに 病院へ 行ったから","自分の かぜで 病院へ 行ったから","電車が おくれたから","ねぼうしたから"],"a":0,"ex":"늦잠도 전철 지연도 아니고, 길을 모르는 할머니와 함께 병원까지 갔기 때문입니다.","au":"49b99cfee558"},{"part":"ポイント理解","q":"女の人は 旅行で 何が いちばん よかったと 言って いますか。","listen":[{"s":"N","t":"男の人と 女の人が 旅行の 話を して います。女の人は 旅行で 何が いちばん よかったと 言って いますか。"},{"s":"M","t":"北海道 旅行、どうだった？"},{"s":"F","t":"楽しかったよ。料理も おいしかったし、ホテルも きれいだった。"},{"s":"M","t":"いいね。ゆきも 見た？"},{"s":"F","t":"うん。でも いちばん よかったのは、ぼくじょうで 子牛に ミルクを あげた ことかな。"},{"s":"N","t":"女の人は 旅行で 何が いちばん よかったと 言って いますか。"}],"choices":["ホテルが きれいだった こと","料理が おいしかった こと","ゆきを 見た こと","子牛に ミルクを あげた こと"],"a":3,"ex":"「でも いちばん よかったのは」 뒤가 답입니다. 요리·호텔·눈은 좋았던 것 중 하나일 뿐입니다.","au":"bb9fb4ff0069"},{"part":"ポイント理解","q":"男の人は あした 何で くうこうへ 行きますか。","listen":[{"s":"N","t":"女の人と 男の人が 話して います。男の人は あした 何で くうこうへ 行きますか。"},{"s":"F","t":"あした 何時の ひこうき？"},{"s":"M","t":"十時。くうこうまで バスで 行こうと 思って いたんだけど、朝は 道が こむらしいんだ。"},{"s":"F","t":"じゃあ、電車の ほうが いいんじゃない？"},{"s":"M","t":"うん。でも 電車は 乗りかえが 二回も あって、にもつが 多いから たいへんなんだ。だから、タクシーで 行く ことに したよ。"},{"s":"F","t":"そう。高いけど、楽だね。"},{"s":"N","t":"男の人は あした 何で くうこうへ 行きますか。"}],"choices":["友だちの 車","電車","タクシー","バス"],"a":2,"ex":"버스는 길이 막히고 전철은 갈아타기가 힘들어서 「タクシーで 行く ことに した」라고 했습니다.","au":"2bab70994429"},{"part":"ポイント理解","q":"男の人は ぜんぶで いくら はらいますか。","listen":[{"s":"N","t":"店で 男の人と 店の 人が 話して います。男の人は ぜんぶで いくら はらいますか。"},{"s":"M","t":"すみません、この りんご、一つ いくらですか。"},{"s":"F","t":"一つ 百円です。五つ 買うと 四百円に なりますよ。"},{"s":"M","t":"じゃあ、五つ ください。それと、この みかんも。"},{"s":"F","t":"みかんは 一ふくろ 三百円です。"},{"s":"M","t":"じゃあ、みかんも 一ふくろ おねがいします。"},{"s":"N","t":"男の人は ぜんぶで いくら はらいますか。"}],"choices":["七百円","四百円","八百円","五百円"],"a":0,"ex":"사과 5개는 할인되어 400엔, 귤 한 봉지 300엔으로 합계 700엔입니다. 사과를 한 개 100엔으로 계산하면 800엔 함정.","au":"d6d996d7a643"},{"part":"発話表現","q":"[그림] 친구 집에 들어갑니다. 뭐라고 말합니까?","listen":[{"s":"N","t":"友だちの 家に 入ります。何と 言いますか。"}],"spoken":["いってきます。","おじゃまします。","おかえりなさい。"],"choices":["1","2","3"],"a":1,"ex":"남의 집에 들어갈 때는 「おじゃまします」. いってきます는 내 집에서 나갈 때, おかえりなさい는 돌아온 사람을 맞을 때 씁니다.","au":"254692ee31a1"},{"part":"発話表現","q":"[그림] 회사 선배가 무거운 짐을 많이 들고 있습니다. 도와 드리고 싶습니다. 뭐라고 말합니까?","listen":[{"s":"N","t":"会社の せんぱいが 重い にもつを たくさん 持って います。てつだいたいです。何と 言いますか。"}],"spoken":["一つ お持ちしましょうか。","一つ お持ちに なりますか。","一つ 持って いただけませんか。"],"choices":["1","2","3"],"a":0,"ex":"내가 해 드리겠다는 제안은 「お～しましょうか」. 持って いただけませんか는 상대에게 부탁하는 말이라 반대입니다.","au":"02d7a6066d3b"},{"part":"発話表現","q":"[그림] 옷 가게에서 다른 색 옷을 보고 싶습니다. 점원에게 뭐라고 말합니까?","listen":[{"s":"N","t":"服の 店で、ほかの 色の 服が 見たいです。店の 人に 何と 言いますか。"}],"spoken":["ほかの 色を 見て くださいませんか。","ほかの 色を 見せて いただけませんか。","ほかの 色を 見せましょうか。"],"choices":["1","2","3"],"a":1,"ex":"보여 달라는 부탁은 「見せて いただけませんか」. 見せましょうか는 내가 보여 주겠다는 말, 見て くださいませんか는 '봐 달라'는 뜻입니다.","au":"b68c7d4489eb"},{"part":"発話表現","q":"[그림] 입원한 친구 병문안을 마치고 돌아가려고 합니다. 친구에게 뭐라고 말합니까?","listen":[{"s":"N","t":"入院して いる 友だちの お見まいに 来ました。帰る とき、友だちに 何と 言いますか。"}],"spoken":["おだいじに。","いただきます。","おめでとう ございます。"],"choices":["1","2","3"],"a":0,"ex":"아픈 사람과 헤어질 때는 「おだいじに」(몸조리 잘하세요)라고 말합니다.","au":"63ddc67dea87"},{"part":"発話表現","q":"[그림] 수업 중 선생님 말씀을 잘 듣지 못했습니다. 다시 한번 말해 달라고 하고 싶습니다.","listen":[{"s":"N","t":"じゅぎょうで 先生の 話が よく 聞こえませんでした。もう 一度 言って ほしいです。何と 言いますか。"}],"spoken":["すみません、もう 一度 申して ください。","すみません、もう 一度 言って あげましょうか。","すみません、もう 一度 おっしゃって いただけませんか。"],"choices":["1","2","3"],"a":2,"ex":"선생님의 행동이므로 존경어 おっしゃる＋いただけませんか. 申す는 나를 낮추는 겸양어라 선생님에게 쓰면 틀립니다.","au":"9e686eacf4b9"}],"shadow":{"jp":"先に 映画館に 行って、チケットを 買って おいて くれる？","r":"さきに えいがかんに いって、チケットを かって おいて くれる？","ko":"먼저 영화관에 가서 티켓을 사 둬 줄래?","au":"13c7de279804"}},{"day":4,"title":"즉시응답 + 약점 문법 보강","vocab":[{"w":"いらっしゃる","r":"いらっしゃる","m":"계시다, 오시다, 가시다","au":"8777cd79050d"},{"w":"召し上がる","r":"めしあがる","m":"드시다","au":"5236d4d78f85"},{"w":"おっしゃる","r":"おっしゃる","m":"말씀하시다","au":"9e1a84bce087"},{"w":"ご覧になる","r":"ごらんになる","m":"보시다","au":"be96abd5d4aa"},{"w":"参る","r":"まいる","m":"가다, 오다(겸양)","au":"d3425e25351c"},{"w":"伺う","r":"うかがう","m":"찾아뵙다, 여쭙다(겸양)","au":"9c0989dfd6c4"},{"w":"拝見する","r":"はいけんする","m":"(삼가) 보다(겸양)","au":"8d62e238c697"},{"w":"さしあげる","r":"さしあげる","m":"드리다","au":"af637f4e5fe2"},{"w":"いただく","r":"いただく","m":"받다, 먹다(겸양)","au":"8f40a5719b7b"},{"w":"しかる","r":"しかる","m":"꾸짖다, 혼내다","au":"85478e35dc92","rep":1},{"w":"ほめる","r":"ほめる","m":"칭찬하다","au":"900a603976f0","rep":1},{"w":"ぬすむ","r":"ぬすむ","m":"훔치다","au":"b1cd86851405","rep":1},{"w":"ふむ","r":"ふむ","m":"밟다","au":"4eefe5296330","rep":1},{"w":"手伝う","r":"てつだう","m":"돕다, 거들다","au":"bc1de59a82c7","rep":1},{"w":"育てる","r":"そだてる","m":"키우다, 기르다","au":"1df75c853efa"}],"lesson":{"summary":"청해 即時応答 8문제와, N4 수험생이 가장 많이 틀리는 문법(수수·조건·수동/사역·경어) 12문제로 약점을 보강합니다.","points":["即時応答: 그림도 보기 글자도 없이 짧은 말 하나를 듣고 바로 고릅니다. 문장 끝(～か/～ましょう/～ても いいですか)과 '누가 하는 행동인지'에 집중하세요.","함정: 질문의 단어를 그대로 되풀이하는 대답이 오답인 경우가 많습니다. 예: 「お借りしても いいですか」→「はい、借ります」(×) / 「ええ、どうぞ」(○).","수수: あげる(내가→남), くれる(남이→나), もらう(내가 남에게서). 윗사람이면 さしあげる·くださる·いただく. 「～て くれる」의 주어는 해 준 사람입니다.","조건: と(자연·기계·길 안내, 뒤에 부탁·의지 불가), ば(뒤에 부탁·의지는 제한), たら(가장 넓게 쓰임, 뒤에 부탁 가능), なら(상대의 말을 받아 조언).","수동·사역: ～れる/られる(당하다), ～せる/させる(시키다), ～させられる(억지로 하다). 사역수동의 주어는 '하기 싫었던 사람'입니다.","경어: 존경어는 윗사람의 행동(いらっしゃる·お～に なる), 겸양어는 나의 행동(伺う·お～する). 상대에게 겸양어를 쓰는 실수가 가장 흔합니다."],"table":{"head":["구분","형태 (書く)","주어","예문"],"rows":[["수동","書かれる","당한 사람","先生に しかられた"],["사역","書かせる","시킨 사람","子どもに 野菜を 食べさせた"],["사역수동","書かせられる","억지로 한 사람","母に そうじを させられた"],["존경","お書きに なる","윗사람","先生が お書きに なった"],["겸양","お書きする","나","先生に 手紙を お書きした"]]},"examples":[{"jp":"友だちが ひっこしを てつだって くれました。","r":"ともだちが ひっこしを てつだって くれました。","ko":"친구가 이사를 도와주었습니다.","au":"b3a300f8abe6"},{"jp":"ラーメンを 食べるなら、駅前の 店が いいですよ。","r":"ラーメンを たべるなら、えきまえの みせが いいですよ。","ko":"라멘을 먹을 거라면 역 앞 가게가 좋아요.","au":"69d7308bc4b1"},{"jp":"電車の 中で 足を ふまれました。","r":"でんしゃの なかで あしを ふまれました。","ko":"전철 안에서 발을 밟혔습니다.","au":"de0f008bb1a8"},{"jp":"先生は いつ 日本へ いらっしゃいますか。","r":"せんせいは いつ にほんへ いらっしゃいますか。","ko":"선생님은 언제 일본에 가십니까?","au":"33ccb58fcb38"}]},"drills":[{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"この ペン、ちょっと お借りしても いいですか。"}],"spoken":["ええ、どうぞ。","いいえ、借りません。","はい、お貸しください。"],"choices":["1","2","3"],"a":0,"ex":"빌려도 되냐는 물음에는 「ええ、どうぞ」. 借りません은 듣는 사람이 빌리는 사람이 아니라서 맞지 않습니다.","au":"2e45b723083d"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"田中さん、きのうは てつだって くれて ありがとう。"}],"spoken":["いいえ、どういたしまして。","いいえ、てつだって ください。","どうも おじゃましました。"],"choices":["1","2","3"],"a":0,"ex":"감사 인사에는 「どういたしまして」. おじゃましました는 남의 집을 나올 때 하는 말입니다.","au":"ada88a42a58b"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"すみません。部長は 何時ごろ おもどりに なりますか。"}],"spoken":["三時ごろ もどって ください。","三時ごろ おもどりしました。","三時ごろ もどる よていです。"],"choices":["1","2","3"],"a":2,"ex":"부장이 몇 시에 돌아오는지 묻고 있으므로 예정을 답합니다. おもどりしました는 시제도 형태도 맞지 않습니다.","au":"9955b909e2b4"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"あ、雨が ふって きましたね。かさ、持って いますか。"}],"spoken":["ええ、かさを 貸して もらいましょう。","いえ、わすれて しまいました。","はい、ふって きました。"],"choices":["1","2","3"],"a":1,"ex":"우산이 있는지 물었으므로 있다/없다로 답해야 합니다. ふって きました는 앞말을 반복한 함정입니다.","au":"97964f5df09b"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"この にもつ、ここに おいても かまいませんか。"}],"spoken":["ええ、おいて ありますよ。","ええ、かまいませんよ。","ええ、おいて しまいましょう。"],"choices":["1","2","3"],"a":1,"ex":"「～ても かまいませんか」(~해도 괜찮습니까)에는 「かまいません」으로 허락합니다.","au":"158cd2d44cbd"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"来週の パーティー、山田さんも 来るでしょうか。"}],"spoken":["さあ、来るか どうか わかりません。","いいえ、来ないで ください。","はい、来て もらいました。"],"choices":["1","2","3"],"a":0,"ex":"앞으로의 일을 추측해 묻고 있으므로 '올지 안 올지 모르겠다'가 자연스럽습니다. 来て もらいました는 과거라 맞지 않습니다.","au":"e0f425c09d5b"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"もう しゅくだいは 終わった？"}],"spoken":["ううん、終わって おいたよ。","ううん、まだ 半分しか して いない。","うん、もう 終わらなかったよ。"],"choices":["1","2","3"],"a":1,"ex":"「まだ ～ていない」로 아직 다 못 했다고 답합니다. もう 終わらなかった·終わって おいた는 틀린 표현입니다.","au":"c2aa913da6e6"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"先生、あしたの 午後、研究室に 伺っても よろしいでしょうか。"}],"spoken":["ええ、伺って ください。","はい、伺いましょう。","ええ、二時ごろ 来て ください。"],"choices":["1","2","3"],"a":2,"ex":"伺う는 학생 자신을 낮추는 겸양어이므로 선생님이 상대에게 「伺って ください」라고 하지 않습니다.","au":"b5fe2baa25db"},{"part":"文法形式","q":"わたしは 先生に 作文を なおして（　　）。","choices":["くださいました","いただきました","くれました","さしあげました"],"a":1,"ex":"주어가 わたし이고 「先生に」이므로 받는 쪽 표현 「～て いただく」. くださる·くれる는 주어가 先生일 때 씁니다."},{"part":"文法形式","q":"友だちが ひっこしを てつだって（　　）、とても たすかりました。","choices":["くれて","もらって","あげて","やって"],"a":0,"ex":"주어 友だち가 나에게 해 준 일이므로 「～て くれる」. もらう는 주어가 받는 사람이어야 합니다."},{"part":"組み立て","q":"妹の たんじょうびに ＿＿ ＿＿ <b>★<\/b> ＿＿ つもりです。","choices":["作って","あげる","チョコレートの","ケーキを"],"a":0,"ex":"완성: 妹の たんじょうびに チョコレートの ケーキを 作って あげる つもりです. ★에는 「作って」. '~해 주다'는 「～て あげる」."},{"part":"文法形式","q":"春に（　　）、いっしょに 花見に 行きましょう。","choices":["なるのに","なったら","なると","なっても"],"a":1,"ex":"뒤에 권유(～ましょう)가 오므로 たら. と는 뒤에 권유·부탁이 올 수 없습니다."},{"part":"文法形式","q":"この ボタンを（　　）、きっぷが 出ます。","choices":["おすなら","おしても","おすのに","おすと"],"a":3,"ex":"기계 조작의 결과(누르면 반드시 나온다)는 と. なら는 상대의 말을 받아 조언할 때 씁니다."},{"part":"文法形式","q":"A「ラーメンが 食べたいんですが、いい 店を 知りませんか。」<br>B「ラーメンを 食べる（　　）、駅前の まる屋が いいですよ。」","choices":["のに","と","ても","なら"],"a":3,"ex":"상대가 말한 내용(라멘을 먹고 싶다)을 받아서 조언할 때는 なら입니다."},{"part":"文法形式","q":"電車の 中で 足を（　　）、とても いたかったです。","choices":["ふませて","ふませられて","ふまれて","ふんで"],"a":2,"ex":"다른 사람이 내 발을 밟은 것이므로 수동(피해) 「ふまれる」. ふませる는 시키다, ふんで는 내가 밟았다는 뜻입니다."},{"part":"文法形式","q":"部長は 新しい 社員に かいぎの しりょうを（　　）。","choices":["作られました","作りたがりました","作らせました","作らせられました"],"a":2,"ex":"부장이 신입 사원에게 시킨 일이므로 사역 「作らせる」. 作らせられる는 시킴을 당한 사람이 주어일 때 씁니다."},{"part":"文法形式","q":"子どもの とき、母に 毎日 自分の 部屋の そうじを（　　）。ほんとうは したく なかったです。","choices":["されました","させられました","させました","して あげました"],"a":1,"ex":"하기 싫었는데 엄마가 시켜서 한 일이므로 사역수동 「させられる」. されました는 엄마가 대신 청소했다는 뜻이 됩니다."},{"part":"文法形式","q":"おきゃくさま、こちらで 少々（　　）ください。","choices":["お待って","待たれて","お待ち","お待ちして"],"a":2,"ex":"손님에게 부탁하는 존경 표현은 「お＋ます형＋ください」. お待ちして는 겸양 형태라 손님에게 쓰지 않습니다."},{"part":"文法形式","q":"先生は いつ 日本へ（　　）か。","choices":["伺います","おります","まいります","いらっしゃいます"],"a":3,"ex":"선생님의 행동이므로 존경어 いらっしゃる. 参る·伺う·おる는 모두 나를 낮추는 겸양어입니다."},{"part":"組み立て","q":"A「先生、はっぴょうの ことで そうだんが あるのですが、あした 十時に ＿＿ ＿＿ <b>★<\/b> ＿＿ よろしいでしょうか。」<br>B「ええ、いいですよ。」","choices":["伺って","研究室に","も","先生の"],"a":0,"ex":"완성: あした 十時に 先生の 研究室に 伺って も よろしいでしょうか. ★에는 「伺って」. 「～ても よろしいでしょうか」는 정중하게 허락을 구하는 표현입니다."}],"shadow":{"jp":"先生に 作文を なおして いただきました。","r":"せんせいに さくぶんを なおして いただきました。","ko":"선생님께서 작문을 고쳐 주셨습니다.","au":"52b7b2a19bed"}},{"day":5,"title":"미니 모의고사 25문제 (전 유형)","vocab":[],"lesson":{"summary":"문자·어휘부터 청해까지 모든 유형을 실제 시험 순서대로 섞은 25문제 미니 모의고사입니다. 시간을 재고, 틀린 유형을 기록하세요.","points":["실제 순서대로 풉니다: 문자·어휘 7(6분) → 문법 8(7분) → 독해 4(12분) → 청해 6. 청해 전에 1분 쉬세요.","이번 주에 연습한 순서를 그대로: 読み·表記는 빠르게, 文法은 주어부터, 독해는 질문 먼저, 청해는 보기를 먼저 훑기.","채점 후 틀린 문제 옆에 이유를 하나 적으세요: ① 몰랐다 ② 헷갈렸다 ③ 시간 부족 ④ 실수.","가장 많이 틀린 유형과 이유가 12주(모의고사 ②) 전에 집중할 부분입니다. ②가 많으면 금요일의 '헷갈리는 문법' 표를 다시 보세요."],"table":{"head":["구간","문항","목표 시간"],"rows":[["문자·어휘","7","6분"],["문법","8","7분"],["독해","4","12분"],["청해","6","약 8분"]]},"examples":[{"jp":"急いで 走ったので、電車に 間に合いました。","r":"いそいで はしったので、でんしゃに まにあいました。","ko":"서둘러 뛰어서 전철 시간에 맞췄습니다.","au":"6be8d1a23e0c"},{"jp":"まどを 開けた まま ねて しまいました。","r":"まどを あけた まま ねて しまいました。","ko":"창문을 연 채로 자 버렸습니다.","au":"13ee96e618cf"},{"jp":"雨が たくさん ふったので、運動会は 中止に なりました。","r":"あめが たくさん ふったので、うんどうかいは ちゅうしに なりました。","ko":"비가 많이 와서 운동회는 취소되었습니다.","au":"f0ddaeb67d99"}]},"drills":[{"part":"読み","q":"この かばんは 小さいですが、とても <u>重い<\/u>です。","choices":["おそい","かるい","おおい","おもい"],"a":3,"ex":"重い는 「おもい」. 「かるい」는 반대말 軽い의 읽기라 함정입니다."},{"part":"読み","q":"あしたから 新しい 仕事を <u>始めます<\/u>。","choices":["きめます","はしめます","はじめます","しめます"],"a":2,"ex":"始める는 「はじめる」. 「はしめます」는 탁점을 뺀 함정입니다."},{"part":"表記","q":"駅の 前で 友だちを <u>まって<\/u> います。","choices":["特って","待って","持って","侍って"],"a":1,"ex":"「まつ」는 待つ. 持つ(もつ)·特(とく)는 모양이 비슷한 함정입니다."},{"part":"文脈","q":"日本へ 来たら、（　　）わたしの 家に あそびに 来て ください。","choices":["なかなか","たいてい","ぜひ","ちょうど"],"a":2,"ex":"부탁·권유를 강하게 할 때는 「ぜひ ～て ください」. なかなか는 보통 부정과 함께 씁니다."},{"part":"文脈","q":"この 道は 夜に なると（　　）ので、一人で 歩かない ほうが いいです。","choices":["重い","軽い","暗い","うれしい"],"a":2,"ex":"밤이 되면 '어두워서' 혼자 걷지 않는 게 좋다는 흐름입니다."},{"part":"言い換え","q":"その 話を 聞いて、<u>びっくりしました<\/u>。","choices":["その 話を 聞いて、おどろきました。","その 話を 聞いて、おこりました。","その 話を 聞いて、よろこびました。","その 話を 聞いて、なきました。"],"a":0,"ex":"びっくりする＝おどろく(놀라다). よろこぶ는 기뻐하다, おこる는 화내다입니다."},{"part":"用法","q":"「間に合う」の 使い方として いちばん いいものを えらんでください。","choices":["急いで 走ったので、電車に 間に合いました。","もう 時間が 間に合ったので、帰りましょう。","友だちと 駅で 間に合いました。","この くつは わたしの 足に 間に合います。"],"a":0,"ex":"間に合う는 '정해진 시간에 늦지 않다'. 발에 맞다는 合う, 친구를 만나다는 会う를 씁니다."},{"part":"文法形式","q":"この 料理は 母に 教えて（　　）作りました。","choices":["やって","もらって","くれて","あげて"],"a":1,"ex":"「母に ～て もらう」로 엄마가 가르쳐 준 것을 나타냅니다. くれる를 쓰려면 「母が 教えて くれて」가 되어야 합니다."},{"part":"文法形式","q":"この 薬を（　　）、すぐ ねつが 下がりました。","choices":["飲むなら","飲んだら","飲んでも","飲むのに"],"a":1,"ex":"'~했더니(그 결과)'는 たら＋과거. なら는 아직 하지 않은 일에 조언할 때 씁니다."},{"part":"文法形式","q":"先生、この 写真を もう（　　）か。","choices":["ご覧に なりました","お見に なりました","拝見しました","見させました"],"a":0,"ex":"선생님의 행동이므로 존경어 ご覧に なる. 拝見する는 나의 행동에 쓰는 겸양어입니다."},{"part":"文法形式","q":"まどを 開けた（　　）ねて しまったので、かぜを ひきました。","choices":["まま","ところ","あいだ","ばかり"],"a":0,"ex":"「～た まま」는 '~한 상태 그대로'. 창문을 연 채로 자 버렸다는 뜻입니다."},{"part":"文法形式","q":"わたしは 弟に ケーキを（　　）、とても おこりました。","choices":["食べて もらって","食べさせられて","食べさせて","食べられて"],"a":3,"ex":"동생이 내 케이크를 먹어서 화가 난 것이므로 피해 수동 「食べられる」입니다."},{"part":"組み立て","q":"A「何を して いるんですか。」<br>B「来週 国へ ＿＿ ＿＿ <b>★<\/b> ＿＿ いる ところです。」","choices":["帰る","友だちに","書いて","手紙を"],"a":3,"ex":"완성: 来週 国へ 帰る 友だちに 手紙を 書いて いる ところです. ★에는 「手紙を」."},{"part":"組み立て","q":"雨が ＿＿ ＿＿ <b>★<\/b> ＿＿ 中止に なりました。","choices":["ふった","たくさん","ので","運動会は"],"a":2,"ex":"완성: 雨が たくさん ふった ので 運動会は 中止に なりました. ★에는 「ので」."},{"part":"文章の文法","q":"先週の 日曜日、わたしは 友だちと 山へ 行きました。朝 早く 出発したので、とても ねむかったです。山の 上に 着くと、きれいな 町が 見えました。<b>[ 1 ]<\/b>、急に 雨が ふって きたので、すぐに 下りました。今度は 天気の いい 日に また 行きたいです。<br><br>[ 1 ]に 入る ものは どれですか。","choices":["それに","ところが","それで","だから"],"a":1,"ex":"예쁜 마을이 보였는데 갑자기 비가 와서 내려왔다는 예상 밖의 전개이므로 ところが. それで·だから는 결과, それに는 추가입니다."},{"part":"短文","q":"＜りゅうがくせいの みなさんへ＞<br>十二月二十日（土）に、日本の 学生との こうりゅうかいを します。場所は 学生会館の 一階です。日本の おかしと 飲み物を 用意して います。さんかしたい 人は、十二月十日までに こくさいセンターの 林に 名前を 言って ください。お金は いりません。<br><br>こうりゅうかいに 行きたい 人は どう しなければ なりませんか。","choices":["十二月二十日に お金を はらう。","十二月十日までに 学生会館へ 行く。","おかしと 飲み物を 持って 行く。","十二月十日までに 林さんに 名前を 言う。"],"a":3,"ex":"「さんかしたい 人は、十二月十日までに … 林に 名前を 言って ください」. 돈은 필요 없고 과자·음료는 준비되어 있습니다."},{"part":"中文","q":"わたしは 去年から 毎朝 ジョギングを して います。はじめた りゆうは、けんこうしんだんで 医者に「少し 運動した ほうが いいですよ。」と 言われたからです。<br>はじめは 十分 走るだけで とても つかれました。朝 早く 起きるのも たいへんで、何回も やめようと 思いました。そんな とき、同じ こうえんで 走って いる 七十さいの 男の人と 知り合いました。その 人は 毎朝 一時間も 走って いて、「つづけると、だんだん 楽に なりますよ。」と 教えて くれました。<br>その 人と 話すのが 楽しくて、わたしも 毎朝 こうえんへ 行くように なりました。今では 三十分 走っても あまり つかれません。体も 軽く なって、よく ねられるように なりました。運動は 一人だと つづけるのが むずかしいですが、友だちが いると 楽しく つづけられると 思います。<br><br>この 人が ジョギングを はじめたのは どうしてですか。","choices":["医者に 運動した ほうが いいと 言われたから","友だちと いっしょに 走りたかったから","七十さいの 男の人に さそわれたから","夜 よく ねられなかったから"],"a":0,"ex":"「はじめた りゆうは … 医者に … 言われたからです」. 70세 남성은 시작한 뒤에 만난 사람입니다."},{"part":"中文","q":"わたしは 去年から 毎朝 ジョギングを して います。はじめた りゆうは、けんこうしんだんで 医者に「少し 運動した ほうが いいですよ。」と 言われたからです。<br>はじめは 十分 走るだけで とても つかれました。朝 早く 起きるのも たいへんで、何回も やめようと 思いました。そんな とき、同じ こうえんで 走って いる 七十さいの 男の人と 知り合いました。その 人は 毎朝 一時間も 走って いて、「つづけると、だんだん 楽に なりますよ。」と 教えて くれました。<br>その 人と 話すのが 楽しくて、わたしも 毎朝 こうえんへ 行くように なりました。今では 三十分 走っても あまり つかれません。体も 軽く なって、よく ねられるように なりました。運動は 一人だと つづけるのが むずかしいですが、友だちが いると 楽しく つづけられると 思います。<br><br>この 人は、運動を つづけるには どう したら いいと 思って いますか。","choices":["毎朝 一時間 走る。","一人で しずかに 走る。","いっしょに 運動する 友だちを 作る。","朝 早く 起きる。"],"a":2,"ex":"마지막 문장 「友だちが いると 楽しく つづけられる」가 글쓴이의 생각입니다."},{"part":"情報検索","q":"＜ひかり市 市民プール＞<br>時間：午前9時〜午後9時（月曜日は 休み）<br>料金（二時間）：大人（高校生から）500円 ／ 子ども（中学生まで）200円<br>※ 六さいより 下の 子どもは、大人と いっしょに 入って ください。お金は いりません。<br>※ 午後6時からは、大人は 300円です。<br><br>火曜日の 午後7時に、父（四十さい）と わたし（中学生）と 弟（四さい）の 三人で プールに 行きます。三人で いくら はらいますか。","choices":["900円","700円","400円","500円"],"a":3,"ex":"오후 6시 이후 어른은 300엔, 중학생은 200엔, 6세 미만은 무료라서 300＋200＝500엔입니다."},{"part":"課題理解","q":"男の 学生は あした 何を 持って 来なければ なりませんか。","listen":[{"s":"N","t":"学校で 女の 先生と 男の 学生が 話して います。男の 学生は あした 何を 持って 来なければ なりませんか。"},{"s":"F","t":"あしたは 工場の 見学ですね。九時に 学校の 前に 集まって ください。"},{"s":"M","t":"先生、おべんとうは いりますか。"},{"s":"F","t":"お昼は 工場の 食堂で 食べるので、いりません。でも、工場の 中では 写真が とれないので、ノートと ペンを 持って 来て ください。"},{"s":"M","t":"カメラは いりませんか。"},{"s":"F","t":"ええ、カメラは いりません。"},{"s":"N","t":"男の 学生は あした 何を 持って 来なければ なりませんか。"}],"choices":["カメラ","ノートと ペン","おべんとう","おべんとうと カメラ"],"a":1,"ex":"점심은 공장 식당에서 먹고, 사진을 찍을 수 없으니 노트와 펜을 가져오라고 했습니다.","au":"ba6a90bd0718"},{"part":"課題理解","q":"女の人は このあと まず 何を しますか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話して います。女の人は このあと まず 何を しますか。"},{"s":"M","t":"中村さん、すみませんが、この 手紙を 出して きて もらえませんか。"},{"s":"F","t":"はい。ゆうびんきょくまで 行きますか。"},{"s":"M","t":"いえ、ビルの 前の ポストで いいです。あ、その 前に 切手を はって ください。切手は わたしの つくえの 引き出しに 入って います。"},{"s":"F","t":"わかりました。"},{"s":"N","t":"女の人は このあと まず 何を しますか。"}],"choices":["ポストに 手紙を 入れる","切手を 出して、手紙に はる","ゆうびんきょくへ 手紙を 出しに 行く","切手を 買いに 行く"],"a":1,"ex":"「その 前に 切手を はって ください」. 우표는 책상 서랍에 있으므로 사러 갈 필요가 없고, 우체국까지 갈 필요도 없습니다.","au":"0abdb6202b97"},{"part":"ポイント理解","q":"女の人は どうして パーティーに 行きませんか。","listen":[{"s":"N","t":"男の人と 女の人が 話して います。女の人は どうして パーティーに 行きませんか。"},{"s":"M","t":"土曜日の パーティー、来るよね？"},{"s":"F","t":"行きたかったんだけど、行けなく なっちゃった。"},{"s":"M","t":"え、どうして？ 仕事？"},{"s":"F","t":"ううん、仕事は 休みなんだけど、国から 母が 来る ことに なったの。くうこうまで むかえに 行かなきゃ いけないんだ。"},{"s":"N","t":"女の人は どうして パーティーに 行きませんか。"}],"choices":["母を くうこうまで むかえに 行くから","国へ 帰るから","体の ちょうしが 悪いから","仕事が あるから"],"a":0,"ex":"일은 쉬는 날이고, 어머니가 오셔서 공항에 마중 나가야 하기 때문입니다. 자기가 귀국하는 것이 아닙니다.","au":"36eaf1e5fabc"},{"part":"ポイント理解","q":"二人は 何時に 会いますか。","listen":[{"s":"N","t":"電話で 女の人と 男の人が 話して います。二人は 何時に 会いますか。"},{"s":"F","t":"もしもし、あしたの 買い物、十時に 駅で いい？"},{"s":"M","t":"ごめん、午前中は はいしゃに 行かなきゃ ならないんだ。十二時には 終わると 思うけど。"},{"s":"F","t":"じゃあ、お昼ごはんも いっしょに 食べようよ。十二時半は どう？"},{"s":"M","t":"はいしゃから 駅まで 三十分 かかるから、一時なら だいじょうぶ。"},{"s":"F","t":"わかった。じゃあ、一時ね。"},{"s":"N","t":"二人は 何時に 会いますか。"}],"choices":["十二時半","十二時","一時","十時"],"a":2,"ex":"여자가 12시 반을 제안했지만, 치과에서 역까지 30분 걸려서 1시로 정했습니다.","au":"77c1b6cbf54b"},{"part":"発話表現","q":"[그림] 회의에 늦게 도착했습니다. 회의실에 들어가면서 뭐라고 말합니까?","listen":[{"s":"N","t":"かいぎに おくれて 来ました。かいぎしつに 入る とき、何と 言いますか。"}],"spoken":["お先に しつれいします。","おそく なって すみません。","おつかれさまでした。"],"choices":["1","2","3"],"a":1,"ex":"늦게 왔을 때는 「おそく なって すみません」. お先に しつれいします는 먼저 퇴근할 때, おつかれさまでした는 일이 끝난 뒤 인사입니다.","au":"8c1a4d6213d1"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"この 仕事、あしたまでに できそう？"}],"spoken":["はい、たぶん だいじょうぶだと 思います。","はい、できそうでした。","いいえ、あしたまでです。"],"choices":["1","2","3"],"a":0,"ex":"할 수 있을 것 같은지 묻고 있으므로 가능 여부를 답합니다. できそうでした는 과거라 맞지 않습니다.","au":"91d63a985e16"}],"shadow":{"jp":"まちがえた 問題は、もう 一度 ふくしゅうしましょう。","r":"まちがえた もんだいは、もう いちど ふくしゅうしましょう。","ko":"틀린 문제는 한 번 더 복습합시다.","au":"f06a242d9e65"}}]};
